// Cases everywhere — landing page.
// Skin data comes from skins.js (generated by scripts/build-site.mjs).

// Set this once the extension is live on the Chrome Web Store: the button will link there instead of the .zip.
const CHROME_STORE_URL = "";

const $ = (s) => document.querySelector(s);
const steamImg = (url, size) => `${url}/${size}fx${size}f`;
const rand = (arr) => arr[Math.floor(Math.random() * arr.length)];
const shortName = (name) => name.replace("★ ", "").split(" | ");
const RARITY = { blue: "var(--r-blue)", purple: "var(--r-purple)", pink: "var(--r-pink)", red: "var(--r-red)", gold: "var(--r-gold)" };
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
const finePointer = matchMedia("(pointer: fine)").matches;
const HOVER_POOL = [...SKINS.knives, ...SKINS.gloves, ...SKINS.dopplers, ...SKINS.coverts];

$("#stat-skins").textContent = `${Math.floor(SKINS.total / 100) * 100}+`;

// ---------- downloads: highlight the visitor's platform ----------
const ua = navigator.userAgent;
const os = /Mac/.test(ua) && !/iPhone|iPad/.test(ua) ? "mac" : /Windows/.test(ua) ? "win" : "ext";
document.querySelector(`.dl[data-os="${os}"]`).classList.add("mine");
if (CHROME_STORE_URL) {
  const ext = $("#ext-link");
  ext.href = CHROME_STORE_URL;
  ext.removeAttribute("download");
  ext.innerHTML = "Add to Chrome <small>Chrome Web Store</small>";
}

// ---------- skins popping out of hovered elements ----------
const pops = $("#pops");
function pop(x, y, skin = rand(HOVER_POOL)) {
  const img = new Image();
  img.className = "pop";
  img.src = steamImg(skin.image, 128);
  img.style.left = `${x}px`;
  img.style.top = `${y}px`;
  img.style.setProperty("--dx", `${(Math.random() - 0.5) * 160}px`);
  img.style.setProperty("--dy", `${-70 - Math.random() * 90}px`);
  img.style.setProperty("--rot", `${(Math.random() - 0.5) * 70}deg`);
  img.addEventListener("animationend", () => img.remove());
  pops.append(img);
}
if (!reduceMotion) {
  const last = new WeakMap();
  document.querySelectorAll("[data-pop]").forEach((el) => {
    el.addEventListener("mouseenter", (e) => {
      const now = performance.now();
      if (now - (last.get(el) || 0) < 400) return;
      last.set(el, now);
      pop(e.clientX, e.clientY);
    });
  });
  document.querySelectorAll("[data-burst]").forEach((el) => {
    el.addEventListener("click", (e) => {
      for (let i = 0; i < 7; i++) setTimeout(() => pop(e.clientX, e.clientY), i * 45);
    });
  });
}

// ---------- reel: an automatic case opening, forever ----------
// Spins, eases out onto a skin under the marker, shows it off, then spins again.
// Each new spin starts with skins popping out of the marker. After every stop the strip
// is rebuilt from the winner onward (same position on screen), so it never runs out.
const reelBox = $("#reel-box"), reelTrack = $("#reel"), reelWin = $("#reel-win");
const LANDING_GOLD = [...SKINS.knives, ...SKINS.gloves, ...SKINS.dopplers];
const STRIP = 70;                      // tiles in the strip
const SPIN_MS = 5200, SHOW_MS = 2600;
let strip = [], offset = 0;            // offset = current translateX of the track, in px

const tileHtml = (s) => `<div class="tile" style="--rc:${RARITY[s.rarity]}"><img src="${steamImg(s.image, 256)}" alt=""></div>`;
const filler = () => (Math.random() < 0.08 ? rand(LANDING_GOLD) : rand(SKINS.reel));
const landing = () => (Math.random() < 0.6 ? rand(LANDING_GOLD) : rand(SKINS.coverts));
const tileStep = () => reelTrack.firstElementChild.offsetWidth + parseFloat(getComputedStyle(reelTrack).columnGap);
const leftOfMarker = () => Math.ceil(reelBox.clientWidth / 2 / tileStep()) + 1;

function renderStrip() {
  reelTrack.innerHTML = strip.map(tileHtml).join("");
}
function place(px, ms = 0) {
  offset = px;
  reelTrack.style.transition = ms ? `transform ${ms}ms cubic-bezier(.08, .6, .12, 1)` : "none";
  reelTrack.style.transform = `translateX(${px}px)`;
}
// translateX that puts tile i's center (plus a nudge) under the marker.
const centerOn = (i, nudge = 0) => {
  const w = tileStep();
  return reelBox.clientWidth / 2 - (i * w + (w - parseFloat(getComputedStyle(reelTrack).columnGap)) / 2) + nudge;
};

function spin() {
  const target = 40 + Math.floor(Math.random() * 16);
  strip[target] = landing();
  reelTrack.children[target].outerHTML = tileHtml(strip[target]);

  const r = reelBox.getBoundingClientRect();
  if (r.bottom > 0 && r.top < innerHeight) {
    for (let i = 0; i < 6; i++) setTimeout(() => pop(r.left + r.width / 2, r.top + r.height / 2), i * 60);
  }
  reelBox.classList.remove("landed", "kick");
  reelBox.offsetWidth;                             // restart the kick animation
  reelBox.classList.add("spinning", "kick");
  reelWin.classList.remove("show");
  const w = tileStep();
  place(centerOn(target, (Math.random() - 0.5) * w * 0.6), SPIN_MS);
  setTimeout(() => reelBox.classList.remove("spinning"), SPIN_MS * 0.5);
  setTimeout(() => land(target), SPIN_MS + 100);
}

function land(i) {
  const skin = strip[i];
  reelTrack.children[i].classList.add("win");
  reelBox.classList.add("landed");
  reelWin.textContent = skin.name;
  reelWin.style.setProperty("--rc", RARITY[skin.rarity]);
  reelWin.classList.add("show");
  if (!reduceMotion) setTimeout(() => recycle(i), SHOW_MS);
}

function recycle(i) {
  const keep = leftOfMarker();
  const shift = (i - keep) * tileStep();
  strip = strip.slice(i - keep);
  while (strip.length < STRIP) strip.push(filler());
  renderStrip();
  place(offset + shift);
  reelTrack.children[keep].classList.add("win");   // still the winner, now at index `keep`
  reelTrack.offsetWidth;                           // commit the jump before animating again
  reelTrack.children[keep].classList.remove("win");
  spin();
}

strip = Array.from({ length: STRIP }, filler);
renderStrip();
const startAt = leftOfMarker();
place(centerOn(startAt));
if (reduceMotion) {
  strip[startAt] = landing();
  renderStrip();
  land(startAt);
} else {
  setTimeout(spin, 700);
}

// ---------- floating skins all over the page ----------
// Each floater drifts on its own sine path and moves with scroll at its own depth;
// the one nearest the cursor lights up and shows its name.
const layer = $("#floaters");
const count = innerWidth < 640 ? 7 : 14;
const pool = [...SKINS.knives, ...SKINS.gloves, ...SKINS.dopplers].sort(() => Math.random() - 0.5);
const floaters = pool.slice(0, count).map((skin, i) => {
  const depth = 0.25 + Math.random() * 0.75;   // 0 = far, 1 = close
  const size = (innerWidth < 640 ? 60 : 80) + depth * 70;
  const el = document.createElement("div");
  el.className = "floater";
  el.style.setProperty("--size", `${size}px`);
  el.style.setProperty("--alpha", (0.18 + depth * 0.32).toFixed(2));
  el.style.setProperty("--blur", `${((1 - depth) * 2).toFixed(1)}px`);
  el.style.setProperty("--rc", RARITY[skin.rarity]);
  const [weapon, finish] = shortName(skin.name);
  el.innerHTML = `<img src="${steamImg(skin.image, 256)}" alt=""><span>★ ${weapon}${finish ? ` | ${finish}` : ""}</span>`;
  layer.append(el);
  return {
    el, size, depth,
    // Spread them over a band taller than the screen so scrolling keeps bringing new ones.
    x: (i % 2 ? 0.55 : 0) + Math.random() * 0.45,
    y: (i / count) * 2.2 + Math.random() * 0.15,
    phase: Math.random() * Math.PI * 2,
    speed: 0.15 + Math.random() * 0.25,
    rot: (Math.random() - 0.5) * 50,
  };
});

let mouse = { x: -999, y: -999 };
addEventListener("mousemove", (e) => (mouse = { x: e.clientX, y: e.clientY }), { passive: true });
document.addEventListener("mouseleave", () => (mouse = { x: -999, y: -999 }));

function frame(t) {
  const s = t / 1000;
  const w = innerWidth, h = innerHeight;
  const band = h * 2.4;
  let hot = null, best = 90;
  for (const f of floaters) {
    const drift = reduceMotion ? 0 : 1;
    const px = f.x * w + Math.sin(s * f.speed + f.phase) * 30 * drift;
    // Wrap vertically so floaters cycle through the whole page.
    let py = (f.y * h - scrollY * f.depth * 0.6) % band;
    if (py < -f.size) py += band;
    py += Math.cos(s * f.speed * 0.8 + f.phase) * 20 * drift - f.size * 0.5;
    // Lean slightly away from the cursor.
    const dx = px + f.size / 2 - mouse.x, dy = py + f.size / 2 - mouse.y;
    const dist = Math.hypot(dx, dy);
    if (dist < best) { best = dist; hot = f; }
    const push = finePointer && dist < 220 ? (220 - dist) / 220 * 24 : 0;
    const nx = px + (dist ? dx / dist : 0) * push, ny = py + (dist ? dy / dist : 0) * push;
    f.el.style.transform = `translate(${nx}px, ${ny}px) rotate(${f.rot + Math.sin(s * f.speed + f.phase) * 8 * drift}deg)`;
  }
  for (const f of floaters) f.el.classList.toggle("hot", f === hot && finePointer);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
